#!/usr/bin/env node
/*
 * Bookam mobile app - UI polish update.
 * Run once from the project root:   node apply-bookam-ui-update.js
 *
 * Changes:
 *   - Home: removed the em dash from the empty-state text.
 *   - Search tab: every coloured emoji icon (amenities, rating star,
 *     verified badge, empty states, image fallback) replaced with clean
 *     black-and-white line icons.
 *   - Bottom tabs: smooth shift animation between tabs + a light haptic
 *     tick on each tab press.
 *
 * After it runs:  git add -A && git commit -m "ui polish" && git push
 * Safe to run more than once.
 */
const fs = require('fs');
const path = require('path');

const FILES = {
  "app/tabs/home.tsx": "",
  "app/tabs/explore.tsx": "",
  "app/tabs/_layout.tsx": ""
};

for (const [rel, data] of Object.entries(FILES)) {
  const full = path.join(__dirname, rel);
  fs.mkdirSync(path.dirname(full), { recursive: true });
  fs.writeFileSync(full, Buffer.from(data, 'base64'));
  console.log('  wrote  ' + rel);
}
console.log('\nDone. Next:');
console.log('  git add -A && git commit -m "ui polish: mono search icons, tab transitions" && git push');
console.log('  Reload the app (press r in the expo terminal) to see it.');
